export function appendLayoutVaryPath(
  parentPath: PartialVaryPath | null,
  cacheKey: string,
  paramName: string,
  isRootParam: boolean
): PartialVaryPath {
  const varyPathPart: VaryPathNode = {
    id: paramName,
    value: cacheKey,
    isRootParam,
    parent: parentPath,
  }
  return varyPathPart as PartialVaryPath
