  while (current !== null && next !== null) {
    if (current.value !== next.value) {
      const id = current.id
      if (id === null) {
        // The request key. Callers check that the route structure matches
        // first, so it's always the same.
      } else {
        if (total === null) {
          if (varyParams === null) {
            // We don't know. Assume it read the param.
