    id: original.id,
    value:
      original.id === null || original.isRootParam === true
        ? original.value
        : Fallback,
    isRootParam: original.isRootParam,
    parent:
      original.parent === null
        ? null
        : getShellSegmentVaryPath(original.parent),
  }
  return clone as VaryPath
}
