function pingFullSegmentRevalidation(
  now: number,
  task: PrefetchTask,
  tree: RouteTree<null>,
  fetchStrategy:
    | FetchStrategy.Full
    | FetchStrategy.PPRRuntime
    | FetchStrategy.RuntimeShell
): PendingSegmentCacheEntry | null {
  const revalidatingSegment = readOrCreateRevalidatingSegmentEntry(
    now,
    task.segmentCacheMap,
    fetchStrategy,
    tree
  )
